// TestFilesWithRemainingAgentChanges_UncommittedDeletion tests Copilot's concern:
// if an agent deletes a file and the user doesn't commit the deletion, the file
// won't be in the shadow tree (buildTreeWithChanges treats missing files as deletions).
// The phantom file check would skip it. Does this matter?
func TestFilesWithRemainingAgentChanges_UncommittedDeletion(t *testing.T) {
	t.Parallel()
	dir := setupGitRepo(t)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	// 1. Create a file that the agent will "delete"
	targetFile := filepath.Join(dir, "to_delete.txt")
	require.NoError(t, os.WriteFile(targetFile, []byte("will be deleted"), 0o644))
	wt, err := repo.Worktree()
	require.NoError(t, err)
	_, err = wt.Add("to_delete.txt")
	require.NoError(t, err)
	baseCommitHash, err := wt.Commit("Add file that agent will delete", &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "test@test.com", When: time.Now()},
	})
	require.NoError(t, err)

	// 2. Create shadow branch WITHOUT to_delete.txt (simulates agent deleting it).
	// createShadowBranchWithContent starts from HEAD which includes to_delete.txt,
	// so we need to manually build a shadow tree that excludes it.
	shadowBranchName := checkpoint.ShadowBranchNameForCommit("del1234", "e3b0c4")
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	baseCommit, err := repo.CommitObject(baseCommitHash)
	require.NoError(t, err)
	baseTree, err := baseCommit.Tree()
	require.NoError(t, err)

	// Flatten tree and remove the deleted file
	entries := make(map[string]object.TreeEntry)
	err = checkpoint.FlattenTree(repo, baseTree, "", entries)
	require.NoError(t, err)
	delete(entries, "to_delete.txt") // Agent deleted this file

	treeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
	require.NoError(t, err)

	shadowCommitObj := &object.Commit{
		Author:    object.Signature{Name: "Test", Email: "test@test.com", When: time.Now()},
		Committer: object.Signature{Name: "Test", Email: "test@test.com", When: time.Now()},
		Message:   "Shadow checkpoint (agent deleted to_delete.txt)",
		TreeHash:  treeHash,
	}
	encodedObj := repo.Storer.NewEncodedObject()
	err = shadowCommitObj.Encode(encodedObj)
	require.NoError(t, err)
	shadowHash, err := repo.Storer.SetEncodedObject(encodedObj)
	require.NoError(t, err)

	ref := plumbing.NewHashReference(refName, shadowHash)
	require.NoError(t, repo.Storer.SetReference(ref))

	// 3. Delete file on disk (agent did this) but user doesn't commit
	require.NoError(t, os.Remove(targetFile))

	// 4. User commits something else (not the deletion)
	otherFile := filepath.Join(dir, "other.txt")
	require.NoError(t, os.WriteFile(otherFile, []byte("other changes"), 0o644))
	_, err = wt.Add("other.txt")
	require.NoError(t, err)
	userCommitHash, err := wt.Commit("User commit (not including deletion)", &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "test@test.com", When: time.Now()},
	})
	require.NoError(t, err)

	userCommit, err := repo.CommitObject(userCommitHash)
	require.NoError(t, err)

	// 5. Check: to_delete.txt was touched by agent, not committed by user.
	// It's NOT in the shadow tree (agent deleted it).
	// Current code skips it (same as phantom file).
	committedFiles := map[string]struct{}{"other.txt": {}}
	remaining := filesWithRemainingAgentChanges(context.Background(), repo, shadowBranchName, userCommit,
		[]string{"to_delete.txt", "other.txt"}, committedFiles)

	// The question: should to_delete.txt be in remaining?
	// If yes → Copilot is right, there's a bug.
	// If no → the skip is correct.
	t.Logf("remaining files: %v", remaining)
	t.Logf("to_delete.txt in remaining: %v", contains(remaining, "to_delete.txt"))
}

func contains(slice []string, item string) bool {
	for _, s := range slice {
		if s == item {
			return true
		}
	}
	return false
}

